namespace sv_1383791d90364e78a2eb1c13acdfd4bb.Services;

public class ValidationError
{
    public string FieldName { get; set; } = string.Empty;
    public string ErrorMessage { get; set; } = string.Empty;
}

public class ValidationResult
{
    public bool IsValid => Errors.Count == 0;
    public List<ValidationError> Errors { get; set; } = new();
}

public interface IAppointmentService
{
    Task<List<string>> GetDoctorsAsync();
    Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateOnly date);
    Task<ValidationResult> ValidatePatientAsync(string email, string insuranceProvider, string doctor, string timeSlot);
}

public class AppointmentService : IAppointmentService
{
    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(new List<string>
        {
            "Dr. Smith",
            "Dr. Johnson",
            "Dr. Williams",
            "Dr. Patel"
        });
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateOnly date)
    {
        var slots = new List<string>
        {
            "9:00 AM",
            "10:00 AM",
            "11:00 AM",
            "1:00 PM",
            "2:00 PM",
            "3:00 PM",
            "4:00 PM"
        };

        return Task.FromResult(slots);
    }

    public Task<ValidationResult> ValidatePatientAsync(string email, string insuranceProvider, string doctor, string timeSlot)
    {
        var result = new ValidationResult();

        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            result.Errors.Add(new ValidationError
            {
                FieldName = "Email",
                ErrorMessage = "Account has outstanding balance"
            });
        }

        if (string.Equals(insuranceProvider, "None", StringComparison.OrdinalIgnoreCase)
            && string.Equals(doctor, "Dr. Smith", StringComparison.OrdinalIgnoreCase))
        {
            result.Errors.Add(new ValidationError
            {
                FieldName = "Doctor",
                ErrorMessage = "Selected doctor does not accept self-pay patients"
            });
        }

        if (string.Equals(timeSlot, "10:00 AM", StringComparison.Ordinal))
        {
            result.Errors.Add(new ValidationError
            {
                FieldName = "TimeSlot",
                ErrorMessage = "This slot is no longer available"
            });
        }

        return Task.FromResult(result);
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_1383791d90364e78a2eb1c13acdfd4bb.Services
@inject IAppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h1>Book an Appointment</h1>

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="appointment">
    <DataAnnotationsValidator />

    @* STEP 1 *@
    <fieldset>
        <legend>Patient Information</legend>

        <div class="mb-3">
            <label for="patientName" class="form-label">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="mb-3">
            <label for="email" class="form-label">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
            @if (!string.IsNullOrEmpty(serverErrors.GetValueOrDefault("Email")))
            {
                <div class="validation-message">@serverErrors["Email"]</div>
            }
        </div>

        <div class="mb-3">
            <label for="phone" class="form-label">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="mb-3">
            <label for="insurance" class="form-label">Insurance Provider</label>
            <InputSelect id="insurance" class="form-control" @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>

        @if (!showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">Next</button>
        }
    </fieldset>

    @* STEP 2 *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Appointment Details</legend>

            <div class="mb-3">
                <label for="doctor" class="form-label">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-control" @bind-Value="Model.Doctor">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.Doctor" />
                @if (!string.IsNullOrEmpty(serverErrors.GetValueOrDefault("Doctor")))
                {
                    <div class="validation-message">@serverErrors["Doctor"]</div>
                }
            </div>

            <div class="mb-3">
                <label for="date" class="form-label">Date</label>
                <InputDate id="date" class="form-control" @bind-Value="Model.AppointmentDate" />
                <ValidationMessage For="() => Model.AppointmentDate" />
            </div>

            <div class="mb-3">
                <label for="timeslot" class="form-label">Time Slot</label>
                @if (timeSlots.Count > 0)
                {
                    <InputSelect id="timeslot" class="form-control" @bind-Value="Model.TimeSlot">
                        <option value="">-- Select --</option>
                        @foreach (var slot in timeSlots)
                        {
                            <option value="@slot">@slot</option>
                        }
                    </InputSelect>
                }
                else
                {
                    <p class="text-muted">Select a doctor and future date, then load available slots.</p>
                }
                <ValidationMessage For="() => Model.TimeSlot" />
                @if (!string.IsNullOrEmpty(serverErrors.GetValueOrDefault("TimeSlot")))
                {
                    <div class="validation-message">@serverErrors["TimeSlot"]</div>
                }
            </div>

            <div class="mb-3">
                <button type="button" class="btn btn-outline-secondary" @onclick="LoadTimeSlots">Load Time Slots</button>
            </div>

            <div class="mb-3">
                <label for="reason" class="form-label">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" @bind-Value="Model.Reason" rows="3" />
                <ValidationMessage For="() => Model.Reason" />
            </div>

            <button type="button" class="btn btn-info me-2" @onclick="CheckAvailability">Check Availability</button>
            <button type="submit" class="btn btn-success">Book Appointment</button>
        </fieldset>
    }
</EditForm>

@if (bookingConfirmed)
{
    <div class="alert alert-success mt-4">Appointment booked successfully!</div>
}

@code {
    private AppointmentModel Model { get; set; } = new();
    private bool showStep2;
    private bool bookingConfirmed;
    private List<string> doctors = new();
    private List<string> timeSlots = new();
    private Dictionary<string, string> serverErrors = new();

    private EditContext? editContext;

    protected override async Task OnInitializedAsync()
    {
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate step 1 fields manually
        var step1Valid = !string.IsNullOrWhiteSpace(Model.PatientName)
            && !string.IsNullOrWhiteSpace(Model.Email)
            && IsValidEmail(Model.Email)
            && !string.IsNullOrWhiteSpace(Model.Phone)
            && !string.IsNullOrWhiteSpace(Model.InsuranceProvider);

        if (step1Valid)
        {
            showStep2 = true;
        }
        else
        {
            // Trigger validation display by creating a new EditContext
            editContext = new EditContext(Model);
            editContext.Validate();
        }
    }

    private async Task LoadTimeSlots()
    {
        if (!string.IsNullOrWhiteSpace(Model.Doctor) && Model.AppointmentDate > DateOnly.FromDateTime(DateTime.Today))
        {
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(Model.Doctor, Model.AppointmentDate);
        }
    }

    private async Task CheckAvailability()
    {
        serverErrors.Clear();

        var result = await AppointmentService.ValidatePatientAsync(
            Model.Email,
            Model.InsuranceProvider,
            Model.Doctor ?? string.Empty,
            Model.TimeSlot ?? string.Empty);

        if (!result.IsValid)
        {
            foreach (var error in result.Errors)
            {
                serverErrors[error.FieldName] = error.ErrorMessage;
            }
        }
    }

    private void HandleSubmit()
    {
        if (serverErrors.Count == 0)
        {
            bookingConfirmed = true;
        }
    }

    private static bool IsValidEmail(string email)
    {
        try
        {
            var addr = new System.Net.Mail.MailAddress(email);
            return addr.Address == email;
        }
        catch
        {
            return false;
        }
    }

    public class AppointmentModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Patient name is required.")]
        public string PatientName { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Email is required.")]
        [System.ComponentModel.DataAnnotations.EmailAddress(ErrorMessage = "Invalid email format.")]
        public string Email { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Phone is required.")]
        public string Phone { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Insurance provider is required.")]
        public string InsuranceProvider { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Doctor is required.")]
        public string Doctor { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Date is required.")]
        [FutureDate(ErrorMessage = "Date must be in the future.")]
        public DateOnly AppointmentDate { get; set; } = DateOnly.FromDateTime(DateTime.Today.AddDays(1));

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Time slot is required.")]
        public string TimeSlot { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Reason for visit is required.")]
        [System.ComponentModel.DataAnnotations.MaxLength(500, ErrorMessage = "Reason cannot exceed 500 characters.")]
        public string Reason { get; set; } = string.Empty;
    }

    public class FutureDateAttribute : System.ComponentModel.DataAnnotations.ValidationAttribute
    {
        public override bool IsValid(object? value)
        {
            if (value is DateOnly date)
            {
                return date > DateOnly.FromDateTime(DateTime.Today);
            }
            return false;
        }
    }
}

