                <button type="button" class="btn btn-outline-secondary" @onclick="LoadTimeSlots">Load Time Slots</button>
            </div>

            <div class="mb-3">
                <label for="reason" class="form-label">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" @bind-Value="Model.Reason" rows="3" />
                <ValidationMessage For="() => Model.Reason" />
            </div>

            <button type="button" class="btn btn-info me-2" @onclick="CheckAvailability">Check Availability</button>
            <button type="submit" class="btn btn-success">Book Appointment</button>
